package local.pitv;
import java.io.*;import java.util.*;import java.util.zip.*;
final class GuideSnapshot {
 static final int MAGIC=0x50544731;static final long WEEK=7L*24*60*60*1000;
 static boolean guideFresh(long updated,long now){return updated>0&&now>=updated&&now-updated<86400000L;}
 static boolean fresh(long updated,long now){return updated>0&&now>=updated&&now-updated<WEEK;}
 static void string(DataOutputStream out,String text)throws Exception{byte[] data=(text==null?"":text).getBytes("UTF-8");if(data.length>1024*1024)throw new IOException();out.writeInt(data.length);out.write(data);}
 static String string(DataInputStream in)throws Exception{int length=in.readInt();if(length<0||length>1024*1024)throw new IOException();byte[] data=new byte[length];in.readFully(data);return new String(data,"UTF-8");}
 static void write(File file,File xml,int rules,Map<String,List<XmlGuide.Programme>> data)throws Exception{File temp=new File(file.getPath()+".tmp");try{try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new GZIPOutputStream(new FileOutputStream(temp))))){out.writeInt(MAGIC);out.writeLong(xml.lastModified());out.writeInt(rules);out.writeInt(data.size());for(Map.Entry<String,List<XmlGuide.Programme>> entry:data.entrySet()){string(out,entry.getKey());out.writeInt(entry.getValue().size());for(XmlGuide.Programme p:entry.getValue()){out.writeLong(p.start);out.writeLong(p.stop);string(out,p.title);string(out,p.description);}}}if(!temp.renameTo(file))throw new IOException("Snapshot rename failed");}finally{if(temp.exists())temp.delete();}}
 static Map<String,List<XmlGuide.Programme>> read(File file,File xml,int rules)throws Exception{if(!file.isFile()||!xml.isFile())return null;try(DataInputStream in=new DataInputStream(new BufferedInputStream(new GZIPInputStream(new FileInputStream(file))))){if(in.readInt()!=MAGIC||in.readLong()!=xml.lastModified()||in.readInt()!=rules)return null;int channels=in.readInt();if(channels<0||channels>100000)throw new IOException();Map<String,List<XmlGuide.Programme>> result=new HashMap<>();XmlGuide.TextPool titles=new XmlGuide.TextPool(),descriptions=new XmlGuide.TextPool();long now=System.currentTimeMillis();for(int i=0;i<channels;i++){String channel=string(in);int count=in.readInt();if(count<0||count>500)throw new IOException();List<XmlGuide.Programme> list=new ArrayList<>();for(int j=0;j<count;j++){XmlGuide.Programme p=new XmlGuide.Programme();p.channel=channel;p.start=in.readLong();p.stop=in.readLong();p.title=titles.text(string(in));p.description=descriptions.text(string(in));if(p.stop>now-24*3600000L&&p.start<now+WEEK)list.add(p);}if(!list.isEmpty())result.put(channel,list);}return result;}}
}
